{
  "packet_id": "H6-T04-2",
  "claim_id": "C053",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C053.main",
    "value": "Incomplete follow-up can leave the release effect uncertain.",
    "scope": "A possible limitation, not a finding that follow-up is incomplete.",
    "provenance": {
      "refs": [
        {
          "source_id": "P026",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span explicitly identifies incomplete follow-up as a possible source of uncertainty about the release effect."
    }
  },
  "signal_basis": {
    "component_id": "C053.signal_basis",
    "value": "Compare the proportion reaching a traceable first publication within the predefined observation window, following unresolved histories and separately reporting accounts whose publication opportunity has not occurred.",
    "scope": "The mapping proposes these observations for the release evaluation; their occurrence is assumed for this assessment, rather than reported as a completed finding.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P011",
          "role": "SUPPORT"
